pub struct Receipt {
    pub cents: u64,
}

fn call_gateway(cents: u64) -> Result<u64, String> {
    if cents == 0 {
        return Err("zero".into());
    }
    Ok(cents)
}

pub fn charge(cents: u64) -> Result<Receipt, String> {
    let confirmed = call_gateway(cents)?;
    if confirmed != cents {
        return Err(format!("gateway confirmed {confirmed}, asked {cents}"));
    }
    Ok(Receipt { cents })
}

